export function most_common_word(s: string): string | null {
  if (s.length === 0) {
    return null;
  }

  const counts = new Map<string, number>();
  for (const word of s.split(" ")) {
    if (word.length === 0) continue;
    counts.set(word, (counts.get(word) ?? 0) + 1);
  }

  let best: string | null = null;
  let bestCount = 0;
  // Map iteration follows insertion order, i.e. first appearance in s.
  for (const [word, count] of counts) {
    if (count > bestCount) {
      best = word;
      bestCount = count;
    }
  }

  return best;
}

