fn most_common_word(s: String) -> Option[String] {
  if s == "" {
    return None
  }
  let top = s
    |> split(" ")
    |> group_by(|w| w)
    |> sort_desc_by(|g| len(g.1))
    |> first()
  return match top {
    Some(g) => Some(g.0),
    None => None,
  }
}

